slug: readerwriterlockslim-write-inside-read-lock
stack: dotnet
topic: concurrency
level: senior
type: find-bug
grading: auto
tags: [readerwriterlockslim, locks, lock-recursion-exception, caching]
code:
  language: csharp
  harness: statements
  source: |
    Cache cache = new();
    Console.WriteLine(cache.Get("a"));
    Console.WriteLine(cache.Get("a"));

    class Cache
    {
        private readonly ReaderWriterLockSlim rwLock = new();
        private readonly Dictionary<string, int> items = new();

        public int Get(string key)
        {
            rwLock.EnterReadLock();
            try
            {
                if (items.TryGetValue(key, out int value))
                {
                    return value;
                }
                rwLock.EnterWriteLock();
                try
                {
                    int created = key.Length * 10;
                    items[key] = created;
                    return created;
                }
                finally
                {
                    rwLock.ExitWriteLock();
                }
            }
            finally
            {
                rwLock.ExitReadLock();
            }
        }
    }
bugLineSets: [[12, 19], [12], [19]]
fixedSource: |
  Cache cache = new();
  Console.WriteLine(cache.Get("a"));
  Console.WriteLine(cache.Get("a"));

  class Cache
  {
      private readonly ReaderWriterLockSlim rwLock = new();
      private readonly Dictionary<string, int> items = new();

      public int Get(string key)
      {
          rwLock.EnterUpgradeableReadLock();
          try
          {
              if (items.TryGetValue(key, out int value))
              {
                  return value;
              }
              rwLock.EnterWriteLock();
              try
              {
                  int created = key.Length * 10;
                  items[key] = created;
                  return created;
              }
              finally
              {
                  rwLock.ExitWriteLock();
              }
          }
          finally
          {
              rwLock.ExitUpgradeableReadLock();
          }
      }
  }
fixedExpect: { kind: output, value: "10\n10" }
